// Package schema initializes a new database from the canonical MuchoCore schema.
package schema

import (
	"context"
	"database/sql"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
)

// Snapshot generated by full-fixtures.php from all PHP migrations applied to
// an empty database. Only DDL and migration defaults are included.
//
//go:embed schema.json
var snapshot []byte

type Snapshot struct{ Tables, Seed []string }

func Definition() (Snapshot, error) {
	var s Snapshot
	err := json.Unmarshal(snapshot, &s)
	return s, err
}

// Init deliberately refuses non-empty databases. Existing installations retain
// their migration history and are never reinitialized by the HTTP server.
func Init(ctx context.Context, db *sql.DB) error {
	s, err := Definition()
	if err != nil {
		return err
	}
	conn, err := db.Conn(ctx)
	if err != nil {
		return err
	}
	defer conn.Close()
	var acquired int
	if err = conn.QueryRowContext(ctx, `SELECT GET_LOCK('muchocore:schema-migrations',30)`).Scan(&acquired); err != nil {
		return err
	}
	if acquired != 1 {
		return errors.New("cannot acquire schema migration lock")
	}
	defer conn.ExecContext(context.Background(), `SELECT RELEASE_LOCK('muchocore:schema-migrations')`)
	var count int
	err = conn.QueryRowContext(ctx, `SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()`).Scan(&count)
	if err != nil {
		return err
	}
	if count != 0 {
		return errors.New("refusing to initialize a non-empty database")
	}
	if _, err = conn.ExecContext(ctx, `SET FOREIGN_KEY_CHECKS=0`); err != nil {
		return err
	}
	defer conn.ExecContext(context.Background(), `SET FOREIGN_KEY_CHECKS=1`)
	for i, statement := range append(s.Tables, s.Seed...) {
		if _, err = conn.ExecContext(ctx, statement); err != nil {
			return fmt.Errorf("schema initialization failed at statement %d; use a fresh empty database before retrying", i+1)
		}
	}
	return nil
}
